# Keep data according to Credit Notes only: pass credit note IDs so report shows only CN rows (no sale order dump)
credit_note_ids = None
if records:
    credit_notes = records.filtered(lambda m: m.move_type == 'out_refund')
    if credit_notes:
        credit_note_ids = credit_notes.ids
else:
    # No selection: we are in Credit Notes context → use all credit notes so report shows only CN data (e.g. 3 rows for 3 CNs)
    credit_notes = env['account.move'].search([
        ('move_type', '=', 'out_refund'),
        ('state', '!=', 'cancel')
    ], order='invoice_date, name')
    if credit_notes:
        credit_note_ids = credit_notes.ids

report_model = env['ks.part.wise.all.data.report']
file_content = report_model.generate_cn_tracking_xlsx_report(credit_note_ids=credit_note_ids)

attachment = env['ir.attachment'].create({
    'name': 'CN_Tracking_Report.xlsx',
    'type': 'binary',
    'datas': file_content,
    'res_model': 'account.move',
    'mimetype': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
})

action = {
    'type': 'ir.actions.act_url',
    'url': '/web/content/' + str(attachment.id) + '?download=true',
    'target': 'self',
}
